/**
 * The short code an account reads out to a coordinator so it can be added to
 * a group. Generated by `public.gen_join_code()` in migration 0006.
 *
 * Lives apart from the action that uses it because a `"use server"` module may
 * only export async functions, and this is neither async nor a server action.
 */

/**
 * A join code as it will be compared: upper case, no spaces, one dash in the
 * middle. People retype these from a screenshot, so "k7p4r2mq" and
 * "K7P4 - R2MQ" have to reach the same row as "K7P4-R2MQ".
 */
export function normalizeJoinCode(raw: string): string {
  const bare = raw.toUpperCase().replace(/[^0-9A-Z]/g, "");
  if (bare.length !== 8) return bare;
  return `${bare.slice(0, 4)}-${bare.slice(4)}`;
}
